record-svg.source:
const {vinyl,labelColor,rim} = api.data;
const cx=321, cy=159;
const grooves = Array.from({length:43}, (_,i) => {
  const r = 90+i*3.36;
  const opacity = i%9===0 ? .32 : i%3===0 ? .21 : .125;
  return `<ellipse cx='${cx}' cy='${cy}' rx='${r.toFixed(2)}' ry='${(r*.431).toFixed(2)}' opacity='${opacity}'/>`;
}).join('');
const arc = (r,a,b) => {
  const xy = t => [cx+r*Math.cos(t),cy+r*.431*Math.sin(t)].map(v=>v.toFixed(2)).join(' ');
  return `M${xy(a)} A${r} ${r*.431} 0 0 1 ${xy(b)}`;
};
const highlights = Array.from({length:28}, (_,i) => `<path d='${arc(100+4.72*i, 2.46+i*.006, 2.98+i*.008)}' opacity='${(i%7===0?.25:.11)}'/>`).join('');
const cuts = Array.from({length:59}, (_,i) => {
  const a=.17+i*.0478;
  const x=cx+240*Math.cos(a), y=cy+105*Math.sin(a)+12;
  return `<path d='M${x.toFixed(1)} ${y.toFixed(1)}l-.13 4.8'/>`;
}).join('');
return api.svg(`<svg viewBox='80 54 486 230' xmlns='http://www.w3.org/2000/svg'>
<g stroke='${api.theme.ink}' stroke-width='.87'>
  <path fill='#665f56' opacity='.21' stroke='none' d='M83 166C88 220 195 279 325 280C454 279 562 237 561 166Z'/>
  <path fill='${rim}' d='M82 159H560V175A239 105 0 0 1 82 175Z'/>
  <path fill='none' stroke='#d2d1c4' stroke-width='.86' d='M83 169A238 106 0 0 0 559 169'/>
  <path fill='none' stroke='#5b6668' stroke-width='.64' d='M82 172A239 106 0 0 0 560 172'/>
  <g stroke='#596164' stroke-width='.64' opacity='.83'>${cuts}</g>
  <path fill='#292b2a' d='M86 159H556V164A235 102 0 0 1 86 164Z'/>
  <ellipse cx='321' cy='159' rx='235' ry='101.3' fill='${vinyl}' stroke='#333532'/>
  <g fill='none' stroke='#a2aaa5' stroke-width='.51'>${grooves}</g>
  <g fill='none' stroke='#cad1c6' stroke-width='.79'>${highlights}</g>
  <path d='${arc(232, .31, 2.81)}' fill='none' stroke='#838984' stroke-width='.67' opacity='.75'/>
  <ellipse cx='321' cy='159' rx='82' ry='35.5' fill='#2d3231' stroke='#252827' stroke-width='.7'/>
  <ellipse cx='321' cy='159' rx='75' ry='32.4' fill='${labelColor}' stroke='#565e5d' stroke-width='.76'/>
  <ellipse cx='321' cy='159' rx='68' ry='29.1' fill='none' stroke='#d8dcd0' stroke-width='.6'/>
  <ellipse cx='321' cy='159' rx='59' ry='25.3' fill='none' stroke='#647779' opacity='.65' stroke-width='.48'/>
  <path d='${arc(49, .31, 2.81)}' fill='none' stroke='#dce1d8' stroke-width='.66'/>
  <ellipse cx='321' cy='159' rx='18' ry='7.7' fill='#b3bfb9' stroke='#778787' stroke-width='.53'/>
  <ellipse cx='321' cy='159' rx='6.8' ry='3.1' fill='#414949' stroke-width='.55'/>
  <path fill='#b9c3bf' d='M317.6 158.5V149.8Q321 146.2 324.4 149.8V158.5Q321 161.2 317.6 158.5Z'/>
  <path fill='none' stroke='#e0e3d8' stroke-width='.67' d='M319 150V157.8'/>
</g>
</svg>`);
